<section class="panel"><div class="panel-header"><div><h2>Personal técnico</h2><p class="muted">Técnicos y especialidades</p></div><?php if (puede('tecnicos')) : ?><button class="btn btn-primary" type="button" data-open="form-tecnico">Nuevo técnico</button><?php endif; ?></div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Teléfono</th><th>Especialidad</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>
